// The logo path for a slug, or "" when there is no file — in which case the
// client renders the coloured initials tile.
function logoPathFor(slug) {
  const key = String(slug || "").trim().toLowerCase();
  if (!key) return "";
  if (LOGO_ALIASES[key]) return "assets/logos/" + LOGO_ALIASES[key];
  return LOGO_FILES.has(key + ".png") ? "assets/logos/" + key + ".png" : "";
}

module.exports = { LOGO_FILES, LOGO_ALIASES, logoPathFor };
